INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (225, 'zhTW', '獸人，在我有生之年我還沒看過這種...', NULL, '我們在這裡的裝備嚴重不足，難以應戰。$B$B必須先做好準備才行...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 1244 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (1244, 'zhTW', '哎呀，這不是一位年輕氣盛的$c嗎，想必是聽聞了我在戰場上的英勇事蹟才來到這裡的吧!$B$B現在可沒時間講故事了，因為還有偉大而重要的任務等著人去完成!所以如果你正在尋找榮耀，那今天算你走運了...', '哎呀，這不是一位年輕氣盛的$c嗎，想必是聽聞了我在戰場上的英勇事蹟才來到這裡的吧!$B$B現在可沒時間講故事了，因為還有偉大而重要的任務等著人去完成!所以如果你正在尋找榮耀，那今天算你走運了...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2566 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2566, 'zhTW', '你可以在智慧谷，葛羅瑪許堡，索爾的顧問群中找到大師皮禮諾。', '你可以在智慧谷，葛羅瑪許堡，索爾的顧問群中找到大師皮禮諾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 2673 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (2673, 'zhTW', '我是一名擁有強大力量的法師，一直以來，我都潛心研究精神和記憶，這有利於學習知識和保持學會的知識。要不是我在夜晚聽到一個巨大的聲音說需要我的幫助，我的研究一定已經完成啦。我只在這兒待一會兒，免費為你重修天賦。接著我就得離開，而你也要選擇自己的道路。', '我是一名擁有強大力量的法師，一直以來，我都潛心研究精神和記憶，這有利於學習知識和保持學會的知識。要不是我在夜晚聽到一個巨大的聲音說需要我的幫助，我的研究一定已經完成啦。我只在這兒待一會兒，免費為你重修天賦。接著我就得離開，而你也要選擇自己的道路。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 6158 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (6158, 'zhTW', '$n，你準備好完成終極任務了。刻在熔火之心地面上的熾熱的符文是通向火海的導管,它們的存在既是對我們的侵犯，又是火焰之王的力量源泉。必須把它們撲滅!$B$B要熄滅符文，拿一小瓶水之精華。把它倒在符文上,火焰就會熄滅,這會使其變得毫無用處並能削弱我們的敵人!', '嘿，朋友。我叫雷米。我是從東邊的赤脊山來的，想在這裡找點生意做，找生意做。你有沒有……有沒有什麼？？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 7774 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (7774, 'zhTW', '從石頭中傳來雷鳴般的聲音...$B$B你好，指揮官。你從希利蘇斯給議會領主帶來了什麼訊息?', '從石頭中傳來雷鳴般的聲音...$B$B你好，指揮官。你從希利蘇斯給議會領主帶來了什麼訊息?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8121 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8121, 'zhTW', NULL, '珍蒂絲．巴洛夫的日記裡寫滿了關於不死生物的胡言亂語。在書的末尾似乎有一張裁縫圖紙，可以用來製作邪術布袋。這種袋子是術士用來存放靈魂碎片的。你想把這張圖紙抄寫到自己的日記裡嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8122 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8122, 'zhTW', NULL, '珍蒂絲．巴洛夫的日記裡寫滿了關於不死生物的胡言亂語。在書的末尾似乎有一張裁縫圖紙，可以用來製作邪術布袋。這種袋子是術士用來存放靈魂碎片的。你已經知道如何製作這種袋子了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8458 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8458, 'zhTW', '你好，$r。我是辛多雷也是泛稱血精靈的憂日大使。我非常希望我們和部落的新聯結會使雙方互利。', '歡迎您, $r。我是辛多雷也是泛稱血精靈的憂日大使。我非常希望我們和部落的新聯結會使雙方互利。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 8876 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (8876, 'zhTW', '你可以感覺到附近邪惡的氣息嗎，$c?以聖手之名，它必須被淨化!$B$B惡魔毀了我們的家園，阿古斯。我絕對不允許它們出現在我們新的家園，艾澤拉斯!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9690 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9690, 'zhTW', '青少年者的比賽引起冬幕節的大混亂。鐵爐堡的銀行是慶典的中心。', '青少年者的比賽引起冬幕節的大混亂。鐵爐堡的銀行是慶典的中心。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9708 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9708, 'zhTW', '新年節慶最大的慶祝活動在月光林地進行。在雷霆崖長者高地那裡的德魯伊們將可以傳送你過去。', '新年節慶最大的慶祝活動在月光林地進行。在雷霆崖長者高地那裡的德魯伊們將可以傳送你過去。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9715 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9715, 'zhTW', '去鐵爐堡的秘法區並且與那裡的夜精靈德魯伊們講話。他們能送你到月光林地參加新年節慶慶祝活動。', '去鐵爐堡的秘法區並且與那裡的夜精靈德魯伊們講話。他們能送你到月光林地參加新年節慶慶祝活動。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9935 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9935, 'zhTW', '又一個士兵往$g他:她;去榮譽堡的路上了...以庫德蘭的鬍鬚為名，他們需要幫助!', '又一個士兵往$g他:她;去榮譽堡的路上了...以庫德蘭的鬍鬚為名，他們需要幫助!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 9991 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (9991, 'zhTW', '又一個士兵往$g他:她;去榮譽堡的路上了...以庫德蘭的鬍鬚為名，他們需要幫助!', '又一個士兵往$g他:她;去榮譽堡的路上了...以庫德蘭的鬍鬚為名，他們需要幫助!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10635 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10635, 'zhTW', '什麼?這是哪裡?這根本不對!看看你!看看這個地方!這不在我的清單上!肯定會有非常多的文書工作...$B$B<那些哥布林在小筆記本里瘋狂地寫著。>$B$B看，如果你已經沒有比站在那裡發呆更好的事可做，你怎麼不去拜訪我在主要城市之一的表弟，丘位元·傳播者?聽說他正在處理奧格瑪，暴風城，雷霆崖，鐵爐堡，幽暗城和達納蘇斯的事。去吧，離開這裡!', '什麼?這是哪裡?這根本不對!看看你!看看這個地方!這不在我的清單上!肯定會有非常多的文書工作...$B$B<那些哥布林在小筆記本里瘋狂地寫著。>$B$B看，如果你已經沒有比站在那裡發呆更好的事可做，你怎麼不去拜訪我在主要城市之一的表弟，丘位元·傳播者?聽說他正在處理奧格瑪，暴風城，雷霆崖，鐵爐堡，幽暗城和達納蘇斯的事。去吧，離開這裡!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10738 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10738, 'zhTW', '等你拜訪完這個奇特的城市，或許你就會有興趣和我們一起慶祝。新年慶典在月光林地進行;其他城市有傳送點可前往慶祝。一起來加入其他的狂歡者吧!', '等你拜訪完這個奇特的城市，或許你就會有興趣和我們一起慶祝。新年慶典在月光林地進行;其他城市有傳送點可前往慶祝。一起來加入其他的狂歡者吧!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 10982 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (10982, 'zhTW', '忘卻你的秘法製衣技能可不是件能輕易決定的事。如果你選擇放棄，你將會忘記所有需要秘法製衣才能製作的配方!$B$B你確定要這麼做嗎?', '忘卻你的秘法製衣技能可不是件能輕易決定的事。如果你選擇放棄，你將會忘記所有需要秘法製衣才能製作的配方!$B$B你確定要這麼做嗎?$B', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12117 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12117, 'zhTW', '如果你想要進行消防演練，這裡就是了。在這附近可能會有一堆雪，不過你永遠不知道何時鋼架或是那些地精們會引起爆炸，對吧?', '如果你想要進行消防演練，這裡就是了。在這附近可能會有一堆雪，不過你永遠不知道何時鋼架或是那些地精們會引起爆炸，對吧?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12971 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12971, 'zhTW', '很高興再次見到你，$n。希望你在俱樂部裡玩的開心。', '很高興再次見到你，$n。希望你在俱樂部裡玩的開心。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 12973 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (12973, 'zhTW', '嘿，$n!我希望你喜歡我們的俱樂部!', '嘿，$n!我希望你喜歡我們的俱樂部!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13467 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13467, 'zhTW', '欺詐者法師領主厄隆保護著第三道環。他看起來單獨一人並且毫無戒備，但是別被他的外貌給欺騙了!厄隆是位強大的咒術師，控制一整群的幻魅生物。到上面把他找出來。', '欺詐者法師領主厄隆保護著第三道環。他看起來單獨一人並且毫無戒備，但是別被他的外貌給欺騙了!厄隆是位強大的咒術師，控制一整群的幻魅生物。到上面把他找出來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 13578 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (13578, 'zhTW', '你的等級還不足以參加暴風之眼的戰鬥。等你獲得更多經驗的時候再回來。', '你的等級還不足以參加暴風之眼的戰鬥。等你獲得更多經驗的時候再回來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14125 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14125, 'zhTW', '我可以幫你嗎?', '我可以幫你嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14289 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14289, 'zhTW', '<艾琳迪雅的身體輕飄飄地浮在海浪上。看來她已經死了有一斷時間了。>', '<艾琳迪雅的身體輕飄飄地浮在海浪上。看來她已經死了有一斷時間了。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14290 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14290, 'zhTW', '<就在你把巴瑞薩斯無生氣的身體由水中轉過來時，他頭上致命的傷口清楚讓你瞭解他為什麼沒有活下來。>', '<就在你把巴瑞薩斯無生氣的身體由水中轉過來時，他頭上致命的傷口清楚讓你瞭解他為什麼沒有活下來。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14291 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14291, 'zhTW', '<達蒙德的表情看起來還算是平靜，身體一小部份埋在沙中。>', '<達蒙德的表情看起來還算是平靜，身體一小部份埋在沙中。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14292 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14292, 'zhTW', '<格隆達爾無助地向正在靠近的你移動，但當生命之火熄滅時他的雙臂也垂了下來。>', '<格隆達爾無助地向正在靠近的你移動，但當生命之火熄滅時他的雙臂也垂了下來。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14293 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14293, 'zhTW', '<特倫希斯雙眼的眨動逐漸停止，掩飾了他死前眼中所透露出的悲傷。>', '<特倫希斯雙眼的眨動逐漸停止，掩飾了他死前眼中所透露出的悲傷。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14295 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14295, 'zhTW', '<當你接近她時，夜精轉了過來抓住了你的手。>\n\n對我來說已經太晚了。我們的榮譽刻劃了命運。去吧...可能有其他人還活著，趕快去幫他們。\n\n<她生命結束時，握著你的手也鬆開了。>', '<當你接近她時，夜精轉了過來抓住了你的手。>\n\n對我來說已經太晚了。我們的榮譽刻劃了命運。去吧...可能有其他人還活著，趕快去幫他們。\n\n<她生命結束時，握著你的手也鬆開了。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14296 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14296, 'zhTW', '這...這就是身為凡人...所會感受到的?\n\n<他的聲音隨著瑪芙拉琳呼吸的停止逐漸淡去。>', '這...這就是身為凡人...所會感受到的?\n\n<他的聲音隨著瑪芙拉琳呼吸的停止逐漸淡去。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14297 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14297, 'zhTW', '<當你走近時，你聽到塞瑞利恩呼吸的喘氣聲。如果能很快獲得治療，或許還有活下來的機會。>', '<當你走近時，你聽到塞瑞利恩呼吸的喘氣聲。如果能很快獲得治療，或許還有活下來的機會。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14298 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14298, 'zhTW', '<沃科爾的身體在地上一動也不動。就在你轉身要離開時，一隻手伸出來抓住了你的腳踝。他還活著!>', '<沃科爾的身體在地上一動也不動。就在你轉身要離開時，一隻手伸出來抓住了你的腳踝。他還活著!>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14299 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14299, 'zhTW', '<當你靠近時，沙爾迪恩的喉嚨發出了微弱的聲音。>\n\n救我...拜託。', '<當你靠近時，沙爾迪恩的喉嚨發出了微弱的聲音。>\n\n救我...拜託。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14300 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14300, 'zhTW', '<當你接近時，戈薩拉滾到他那邊注視著你。你看到他臉上浮出了帶著希望的笑容。>', '<當你接近時，戈薩拉滾到他那邊注視著你。你看到他臉上浮出了帶著希望的笑容。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14346 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14346, 'zhTW', '我在精靈走前都不工作!', '我在精靈走前都不工作!', '精靈在森林裡殺了太多苦工。我要坐在這裡，這樣才安全。', '精靈在森林裡殺了太多苦工。我要坐在這裡，這樣才安全。', '我才不要為了一點木頭送命!', '我才不要為了一點木頭送命!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14432 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14432, 'zhTW', '幹什麼，弱小的凡.。$B$B呃...嗯，$r?我能為你做什麼?', NULL, '什麼事，$c?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14454 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14454, 'zhTW', NULL, '你好。', NULL, '要搭便車嗎?', NULL, '有什麼我能幫忙的嗎?', NULL, '很高興見到你。', NULL, '在找便車嗎?', NULL, '你好嗎，$c?', NULL, '外面有點冷，你不覺得嗎?', NULL, '很高興看到你一切安好。');
DELETE FROM `npc_text_locale` WHERE `ID` = 14549 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14549, 'zhTW', NULL, '需要幫忙指路嗎?我對這個地方熟到不能再熟了。', NULL, '看到熊怪都這麼容易被腐化，讓我很難過。牠們曾經是我們的朋友。', NULL, '這個地方到處都是牠們的蹤跡...我們得帶著遺物盡快離開這裡。', NULL, '我沒有看到任何沉睡中的德魯伊。他們一定已經被帶離這裡了。', NULL, '我們早該預料到這一切。腐化已經蔓延了好一段時間了。', NULL, '如果連熊怪都墮落到這種地步，那泰達希爾其他地方又會是什麼樣子?', NULL, '在腐化吞噬我們所有人之前，一定有辦法可以阻止它。', NULL, '該死的，范達爾!你這棵被詛咒的「世界之樹」到底把我們拖進了什麼樣的麻煩?');
DELETE FROM `npc_text_locale` WHERE `ID` = 14555 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14555, 'zhTW', '<野豬人用他閃亮的黑眼珠丁盯著你看。>', NULL, '<野豬人朝你皺了皺鼻子，哼了一聲。>', NULL, '現在又怎樣，$r?儘管放馬過來。', NULL, '我們是戰士，$n。<哼>又多又驕傲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14636 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14636, 'zhTW', '我聽說旅人豐年祭是把你自己的好運分享給周遭眾人的節日。$B$B我們很幸運能找到這個世界以及其中的勇敢居民，將我們的智慧與知識與他們分享應該相當適合。', '我聽說旅人豐年祭是把你自己的好運分享給周遭眾人的節日。$B$B我們很幸運能找到這個世界以及其中的勇敢居民，將我們的智慧與知識與他們分享應該相當適合。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14637 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14637, 'zhTW', '人類釀的酒跟亞麻袋泡水的味道差不多，但他們的確很懂料理。旅人豐年祭?我超喜歡的!', '人類釀的酒跟亞麻袋泡水的味道差不多，但他們的確很懂料理。旅人豐年祭?我超喜歡的!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14638 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14638, 'zhTW', '一個理想的旅人豐年祭慶典所需要物資流通非常的驚人...需要這麼多的稀有材料，這麼多人力，成千上萬的箱子裝著成品被運到這裡，而到處都是豐年祭餐席。$B$B老實說，我很驚訝!而且很餓...我可以聞到南瓜派的香味。你聞到那些派了嗎?', '一個理想的旅人豐年祭慶典所需要物資流通非常的驚人...需要這麼多的稀有材料，這麼多人力，成千上萬的箱子裝著成品被運到這裡，而到處都是豐年祭餐席。$B$B老實說，我很驚訝!而且很餓...我可以聞到南瓜派的香味。你聞到那些派了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14642 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14642, 'zhTW', '獸人跟牛頭人很幸運能找到彼此，因為我們對彼此種族的力量充滿欽佩與崇敬。我們很高興跟他們一起能加入慶典。$B$B就連被遺忘者也參加了，雖然我不在乎他們是為了什麼目的...', '獸人跟牛頭人很幸運能找到彼此，因為我們對彼此種族的力量充滿欽佩與崇敬。我們很高興跟他們一起能加入慶典。$B$B就連被遺忘者也參加了，雖然我不在乎他們是為了什麼目的...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14643 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14643, 'zhTW', '旅人豐年祭是把一個人的好運分享給周遭眾人的時刻。$B$B在莫高雷與部落，我們找到了家園與朋友，來享受眾多的果實。$B$B我們誠心的希望我們所有的盟友都來加入我們的饗宴與慶典。', '旅人豐年祭是把一個人的好運分享給周遭眾人的時刻。$B$B在莫高雷與部落，我們找到了家園與朋友，來享受眾多的果實。$B$B我們誠心的希望我們所有的盟友都來加入我們的饗宴與慶典。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14644 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14644, 'zhTW', '那些牛頭人，他們可瞭解怎麼煮東西。你看到他們端出來的食物嗎?$B$B我要狂吃到掛掉...等回到墓地再吃更多!', '那些牛頭人，他們可瞭解怎麼煮東西。你看到他們端出來的食物嗎?$B$B我要狂吃到掛掉...等回到墓地再吃更多!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14681 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14681, 'zhTW', NULL, '嗨，寶貝!我看起來如何?', NULL, '我好想你喔!你都跑去哪了?$B$B你要回答我，還是要在那邊傻站著?', NULL, '你喜歡我這身打扮嗎?這是要參加派對穿的，我刷了你的帳戶喔。', NULL, '剛剛有另一個男的在跟我搭訕。真是有夠不要臉!$B$B親愛的，你可以幫我揍他一頓嗎?謝啦，愛你喔!', NULL, '我等不及看到你出人頭地的那一天了。想想看，到時候我就能自稱「貿易親王夫人」了$B$B更別提還能買下所有我一直想要的東西了!!!', NULL, '在外面小心點。我聽說海灣裡有南海海盜出沒。$B$B嗯，也許我該親自去看看...', NULL, '我們可以去卡加洛山頂來一場浪漫的野餐嗎?$B$B記得帶上我最愛的香檳喔!', NULL, '你眼神裡透著一絲狡猾，寶貝，你到底在打什麼主意?$B$B說啊?');
DELETE FROM `npc_text_locale` WHERE `ID` = 14683 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14683, 'zhTW', '你太漂亮了!你相信我所說的，對吧，寶貝?', NULL, '甜心，你都跑去哪了?你知道你不跟我報備我會有多擔心嗎!', NULL, '你覺得我的腹肌怎麼樣，寶貝?我剛從健身房回來。$B$B我可是塊上好的肌肉呢!', NULL, '那些其他女人只是朋友而已，寶貝。', NULL, '我喜歡你今天的穿著!', NULL, '我知道我昨晚答應過你，前天晚上也答應過，但明天晚上我一定帶你去個很棒的地方!', NULL, '我聽說稍早有些南海海盜靠岸了。你進城的時候要小心點!$B$B他們甚至還有女海盜!嗯，也許我該親自去查看一下?只是為了確保外面對你來說是安全的，寶貝。', NULL, '我這位性感的公司女強人今天過得如何啊?照你這樣經營下去，我看用不了多久大家就要叫你貿易公主$N了!$B$B我真是等不及了!我就整天泡在健身房，再去泳池邊曬曬我的古銅色肌膚。', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14766 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14766, 'zhTW', '凱麗莎，你還活著!找個地方躲起來，那些東西源源不絕地冒出來!', NULL, '我還在流血嗎?我沒辦法...我撐不了多久了。你有看到任何一位大法師嗎?', NULL, '哼。我想這就是使用魔法的代價吧。種什麼因得什麼果...願艾露恩保佑我們所有人。', NULL, '凱麗莎!大法師賽爾溫在找你。她應該就在附近...', NULL, '這些生物...數量多到數不清。死了好多人!看看阿茲夏拉都燒成什麼樣子了。高等精靈到底做了什麼?', NULL, '我當初為什麼沒有跟其他人一起逃走?他們已經把學院團團包圍了。我們被困在這裡了。', NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14767 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14767, 'zhTW', NULL, '我必須保持秘法結界內的能量。', NULL, '我的力量...開始...衰竭了。凱麗莎，拜託告訴我大法師們有備用計畫...', NULL, '我沒辦法再維持這個護盾多久了。凱麗莎——我們之中有誰能活下來嗎?', NULL, '又有更多這種生物了!牠們到底是從哪冒出來的?首都到底發生了什麼事?', NULL, '凱麗莎!快點——大法師賽爾溫想見你，她說事情很緊急。也許我們還有機會打贏這場仗?', NULL, '我已經竭盡全力維持這些結界了。凱麗莎，快去找一位大法師!我感覺自己快要撐不住了...', NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14796 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14796, 'zhTW', '$N?$G先生:女士;，你才不是獵人，你是個$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14797 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14797, 'zhTW', '喔，你我一定會相處得很愉快。關於獵人之道，我有好多東西要教你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14805 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14805, 'zhTW', '嘿，$g先生:小姐; $N。我沒辦法訓練你魔法之道，不過這雙靈活的手指可是很會按摩肩頸的喔。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14806 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14806, 'zhTW', '今天真是個適合鑽研神秘法術的好日子。你說是吧，$g先生:小姐; $N?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14827 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14827, 'zhTW', NULL, '你為什麼在這干擾我的工作?!快說!', NULL, '你最好有個好理由來找我，小蝦米!', NULL, '這是怎麼回事?你找我到底想幹嘛，小蝦米?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14879 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14879, 'zhTW', '$n，坐下來。這些猴子似乎不喜歡熱熱的火。', NULL, '誰能想到，經歷了這麼多事之後，我們竟然會落到這步田地?', NULL, '嘿，大家看，是$N!', NULL, '看來我們陷入了大麻煩。你覺得你能帶我們離開這裡嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 14880 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (14880, 'zhTW', NULL, '噢，$n，我們被孤立了!', NULL, '我好想念凱贊。我們還能再見到汙水港嗎，$N?', NULL, '過來陪我坐一會兒吧。我們可以生火烤螃蟹，唱唱歌。', NULL, '這件事我全指望你了，你到底打算怎麼帶我們離開這座島?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15110 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15110, 'zhTW', '元素喜歡你。你對它們有什麼要求?', '元素喜歡你。你對它們有什麼要求?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15111 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15111, 'zhTW', '元素不是忠誠的，最好別讓沒受過訓練的人來跟它們打交道。很抱歉，我不需要你的幫忙。', '元素不是忠誠的，最好別讓沒受過訓練的人來跟它們打交道。很抱歉，我不需要你的幫忙。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15117 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15117, 'zhTW', '我的指揮官在我眼前被屠殺了，兄弟們的屍體圍著我到處都是，我無法繼續戰鬥。我太丟臉了，$c，我沒有為他們報仇。', NULL, '我們這些步兵被下令再次衝鋒——衝向一堵長矛之牆——我做不到，$c。武器從我手中滑落，雙腳也動彈不得。$B$B我真是恥辱。', NULL, '別看我，$r。我讓部落蒙羞了。我完了。', NULL, '沒有一個獸人應該像我這樣臨陣脫逃。就讓我獨自承受這份恥辱吧。我情願死在這座塔裡，只是害怕祖先們會如何看待我的懦弱。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15140 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15140, 'zhTW', '你覺得我們什麼時候可以離開?我必須回去工作。', '你覺得我們什麼時候可以離開?我必須回去工作。', '這些穴居人到底是從哪冒出來的?難道牠們一直都住在地底下嗎?', '這些穴居人到底是從哪冒出來的?難道牠們一直都住在地底下嗎?', '你還是自在點比較好。鐵鑄不會讓任何人出去，直到穴居人的騷動平息為止。', '你還是自在點比較好。鐵鑄不會讓任何人出去，直到穴居人的騷動平息為止。', '你有外面的消息嗎?我聽說巨魔那邊也不太平靜。', '你有外面的消息嗎?我聽說巨魔那邊也不太平靜。', '這裡變得越來越擁擠了。我在密閉空間裡待不慣。', '這裡變得越來越擁擠了。我在密閉空間裡待不慣。', '你會以為，經歷了一場毀天滅地的大地震之後，室內會是你最不想待的地方，對吧?', '你會以為，經歷了一場毀天滅地的大地震之後，室內會是你最不想待的地方，對吧?', '$N!聽說你是鐵鑄新收的小跑腿$r。她現在又要你做什麼了?', '$N!聽說你是鐵鑄新收的小跑腿$r。她現在又要你做什麼了?', '我感覺自己好像已經被關在這裡一輩子了。到啤酒節了嗎?', '我感覺自己好像已經被關在這裡一輩子了。到啤酒節了嗎?');
DELETE FROM `npc_text_locale` WHERE `ID` = 15148 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15148, 'zhTW', '火山岩!要買火山岩找我就對了!', NULL, '火山岩特賣!剛從山上挖出來，熱騰騰的!你要的，我都有!', NULL, '火山岩——超低價出清!你一定會愛上我的石頭。', NULL, '快來買你的火山岩!……貓咪也超愛喔!', NULL, '把大災變的一部分帶回家吧!火山岩特賣——熱、熱、超熱!', NULL, '要壓紙?要擋門?要砸窗戶?啪、啪、啪!就是火山岩。', NULL, '火山岩，用途多到數不清。熔岩、咖啡、三溫暖、香蕉……', NULL, '火山岩!限時優惠!還附上正品證明書喔!', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15239 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15239, 'zhTW', '只有獲得遊俠將軍許可的人能進入太陽之井高地。', '只有獲得遊俠將軍許可的人能進入太陽之井高地。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15251 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15251, 'zhTW', '這不是什麼很大的挑戰，老兄，但我們必須確定你能力夠才能帶你進去。', '這不是什麼很大的挑戰，老兄，但我們必須確定你能力夠才能帶你進去。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15252 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15252, 'zhTW', '他們正處於試煉之中，老兄。耐心點。', '他們正處於試煉之中，老兄。耐心點。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15260 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15260, 'zhTW', '我幫不了你，想要接受德魯伊的訓練就去跟贊塔布拉談話。', '我幫不了你，想要接受德魯伊的訓練就去跟贊塔布拉談話。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15263 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15263, 'zhTW', '我幫不了你，想要接受法師的訓練就去跟索拉薩談話。', '我幫不了你，想要接受法師的訓練就去跟索拉薩談話。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
