INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15264, 'zhTW', '我幫不了你，想要接受牧師的訓練就去跟圖那利談話。', '我幫不了你，想要接受牧師的訓練就去跟圖那利談話。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15280 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15280, 'zhTW', '別在那邊窺探，朋友。$B$B如果你想買王冠公司節日商品，你可以去找城裡的可愛商品商人。', '別在那邊窺探，朋友。$B$B如果你想買王冠公司節日商品，你可以去找城裡的可愛商品商人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15299 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15299, 'zhTW', '弄丟了?$B$B我對你非常失望，$n。$B$B那枚戒指可是獨一無二的，是用陣亡英雄們的殘甲碎片，以及從敵人刀刃上提煉出的純淨金屬所打造而成。$B$B別讓這種事再發生了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15348 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15348, 'zhTW', '你是誰?你想要對我們的部族做什麼?', NULL, '娜布莉雅，是你嗎?', NULL, '歡迎你，外來者，來到我們的家園。', NULL, '你是來觀察的嗎?要不要來顆椰子?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15382 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15382, 'zhTW', NULL, '他真的死了，對不對?$B$B我...我可以感覺到。', NULL, '真的沒有辦法救他了嗎?$B$B恐怕我這輩子都會不斷地這樣問自己。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15435 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15435, 'zhTW', '什麼要?', NULL, '食人魔看起來很好笑。', NULL, '我肚子餓。', NULL, '我不喜歡沙子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15460 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15460, 'zhTW', '你是來參加狩獵行動的嗎，$n?', '你是來參加狩獵行動的嗎，$n?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15461 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15461, 'zhTW', '走開，$c。我不需要你參加我的狩獵行動。', '走開，$c。我不需要你參加我的狩獵行動。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15501 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15501, 'zhTW', '喂，我不過是想拿我應得的。', '喂，我不過是想拿我應得的。', '想加入嗎?打了就搶，寶貝!', '想加入嗎?打了就搶，寶貝!', '快點，$c!能拿的全部拿走!', '快點，$c!能拿的全部拿走!', '這些死掉的牛頭人身上就只有珠子跟一堆破爛。你有找到什麼好東西嗎? ', '這些死掉的牛頭人身上就只有珠子跟一堆破爛。你有找到什麼好東西嗎? ', '嘿，$c!這地方已經被翻得差不多了，不過你或許還能找到些值得一看的東西。', '嘿，$c!這地方已經被翻得差不多了，不過你或許還能找到些值得一看的東西。', '哇，你該不會是來抓我們的吧?', '哇，你該不會是來抓我們的吧?', NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15531 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15531, 'zhTW', '希米爾說葛爾多有勇氣，但是沒腦子。他什麼意思?', NULL, '葛多喜歡摘花。摘花有點像殺戮的感覺。', NULL, '外面好像有風。', NULL, '喬安說葛多需要找個裁縫師來修補葛多的肚子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15547 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15547, 'zhTW', '回去，$c。$B$B在大災變發生前，我們找到了些東西。$B$B我們挖出了一些不該被挖出來的東西。$B$B向你的信仰禱告山崩足以把這些東西藏起來吧...', '回去，$c。$B$B在大災變發生前，我們找到了些東西。$B$B我們挖出了一些不該被挖出來的東西。$B$B向你的信仰禱告山崩足以把這些東西藏起來吧...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15569 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15569, 'zhTW', '準備好，$r。$B$B納迦隨時都會發動攻擊。', NULL, '這個地區正是威脅要撕裂我們世界的大災變的震央之一。$B$B如果我們能活下來，就必須設法找出這一切的成因。', NULL, '對這些船隻的攻擊，顯然不是隨機發生的。$B$B我們必須查明納迦在此的真正動機。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15696 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15696, 'zhTW', '你辦到了!我們得救了!', '你辦到了!我們得救了!', '我們終於真的要前往阿茲夏拉了嗎?那裡也有火山嗎?', '我們終於真的要前往阿茲夏拉了嗎?那裡也有火山嗎?', '我該怎麼感謝你才好，$N?', '我該怎麼感謝你才好，$N?', '如果我是你，會多留意周遭的風聲。外面有傳言說卡加洛山跟迷失群島的火山爆發都是你造成的。$B$B我知道，聽起來很離譜。但人們什麼都能拿來八卦，也喜歡扯下英雄的光環，尤其是當中還有利可圖的時候。', '如果我是你，會多留意周遭的風聲。外面有傳言說卡加洛山跟迷失群島的火山爆發都是你造成的。$B$B我知道，聽起來很離譜。但人們什麼都能拿來八卦，也喜歡扯下英雄的光環，尤其是當中還有利可圖的時候。', '趁火山還沒把我們全部毀掉之前，趕快離開碼頭吧!', '趁火山還沒把我們全部毀掉之前，趕快離開碼頭吧!', '只要你準備好，我們隨時可以出發，$g先生:女士;!', '只要你準備好，我們隨時可以出發，$g先生:女士;!', '我也不知道。我想我會懷念這個地方的。我們在這裡有過不少美好的時光。', '我也不知道。我想我會懷念這個地方的。我們在這裡有過不少美好的時光。', '我有個提議……這次我們就別再誤闖聯盟跟部落的海戰現場了。$B$B我只是說說而已。', '我有個提議……這次我們就別再誤闖聯盟跟部落的海戰現場了。$B$B我只是說說而已。');
DELETE FROM `npc_text_locale` WHERE `ID` = 15711 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15711, 'zhTW', 'Thoth\'al amun Ree\'thael vormos! Vormos! Vormos!', NULL, 'Al\'tha, Al\'tha bormaz. Ni bormaz ta\'thall?它來了，它行走於烈焰之中，$r!', NULL, '暗影窺視著。Bo\'al lal arwi C\'toth。終焉將至，披著寂靜之火而來。', NULL, 'Mar\'kowa tallol ye\'tarin，它知道，它都知道。', NULL, '恐懼從無盡之心深處翻騰而出。別逼我看!我已經看到超乎我所能承受的一切了!', NULL, '我們什麼都不是。Tulall par\'okoth。Far\'al, ka\'kar。虛空正在吞噬一切。', NULL, '<暮光僕從朝你發出咕嚕聲，嘴裡冒出白色的泡沫。>', NULL, 'H\'thon，那道延伸至視線之外的黑暗之柱。H\'thon marwol qualar：無盡黑夜的掌握。', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15733 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15733, 'zhTW', '你有聞到什麼嗎?', NULL, '我很想幫忙，但我這邊……有點鎖鏈疹。我還是待在後面好了。', NULL, '你真是個與眾不同的$c，$N。我不是說壞的意思，只是覺得你還挺有趣的。', NULL, '我在那邊掛了多久啊?感覺好像過了好幾天。', NULL, '我不建議像那樣被鏈子吊著。不過老實說，這樣吊著對我的髮型還挺有幫助的。', NULL, '食人魔。$B$B我恨食人魔。', NULL, '你每次要殺東西之前都話這麼多嗎?', NULL, '少廢話。多打食人魔。成交?', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15750 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15750, 'zhTW', '世界的末日正在逼近，$c。但是不需要感到絕望。聽聽我說的話，還有我的兄弟們能幫你們的事。', '世界的末日正在逼近，$c。但是不需要感到絕望。聽聽我說的話，還有我的兄弟們能幫你們的事。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15829 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15829, 'zhTW', '喂!聽說你想要搶貿易親王的飯碗。$B$B是真的嗎?', NULL, '我真想朝那個奇普的臉上揍一拳!我也想親吻那個坎蒂的嘴唇!', NULL, '有人說要開派對嗎?', NULL, '這個卡佳可樂的事讓我開始思考。我們真的希望競爭對手有想法嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15831 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15831, 'zhTW', NULL, '嘿，$g寶貝:帥哥;!你跟那$g小妞:小子;的傳聞是怎麼一回事啊?', NULL, '今天真是個挖掘全世界最後已知卡佳礦床的好日子，你說是吧，$N?', NULL, '很奇怪吧，卡佳礦石在幾千年前讓我們變聰明，但現在對我們的巨魔們似乎完全沒作用?', NULL, '從卡佳礦石中提煉出卡佳可樂，這根本是你天才般的傑作，$N。貿易親王一定很擔心你會搶走他的頭銜!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15963 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15963, 'zhTW', '感謝你撥空協助我們測試《魔獸世界：大災變》的內容。\n\n\n\n你想去哪裡?', '感謝你花時間幫助我們測試《,NULL世界》:浩劫與重生。\n\n你想去哪?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 15982 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (15982, 'zhTW', NULL, '我什麼也不會告訴你的，$r!', NULL, '<瑪莉恩大聲尖叫，狠狠瞪著你。>', NULL, '你們的城市終將淪陷，$r。你會在新政權的黑暗之中滅亡!', NULL, '隨你便吧。我的新主人會在處決你之前，把我的名字刻進你的血肉裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16015 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16015, 'zhTW', '這裡...比之前的地方還要危險，$r。$B$B我們必須趕快找一個更安全的避難所!', NULL, '我們必須找到你的盟友，並查明納迦在此地區的動機。$B$B但首先，我們得先找個更安全的地方。', NULL, '我覺得我們對納迦在這裡的活動所知還只是冰山一角。$B$B我從未見過牠們如此組織嚴密、紀律分明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16019 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16019, 'zhTW', '<受傷士兵痛苦的叫聲被水的聲音給扭曲了。>', '<受傷士兵痛苦的叫聲被水的聲音給扭曲了。>', '<這名受傷的士兵似乎還有呼吸。幸好，他的氣泡罩依然完好。>', '<這名受傷的士兵似乎還有呼吸。幸好，他的氣泡罩依然完好。>', '<士兵的側腹有一道看起來相當痛的傷口。>', '<士兵的側腹有一道看起來相當痛的傷口。>', '<這名士兵似乎是裝死以躲過納迦的懷疑，這很可能救了他一命。>', '<這名士兵似乎是裝死以躲過納迦的懷疑，這很可能救了他一命。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16032 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16032, 'zhTW', '我們面對的比陶土議會所預測的來得恐怖太多了。', NULL, '這個洞穴外聚集了大量的納迦。$B$B我們很幸運能在沒被發現的情況下抵達這裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16033 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16033, 'zhTW', '我們的士兵...他們現在都已經是俘虜了。', NULL, '我們之中有許多人試圖逃離納迦的追擊。$B$B只有我一個人成功了...', NULL, '我不知道為什麼，但那些怪物似乎特意想讓我們的人活下來...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16078 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16078, 'zhTW', '什麼─我在哪?你是暮光之錘的人嗎?', '什麼─我在哪?你是暮光之錘的人嗎?', '一切都結束了嗎?', '一切都結束了嗎?', '必須……回到……鐵樹鎮!', '必須……回到……鐵樹鎮!', '你不是暮光之錘的人。外面到底發生了什麼事?', '你不是暮光之錘的人。外面到底發生了什麼事?', 'I\'m burned. Badly.', 'I\'m burned. Badly.', '暮光之錘……我聽到他們尖叫著逃跑……我們要展開反擊了嗎?', '暮光之錘……我聽到他們尖叫著逃跑……我們要展開反擊了嗎?', '城鎮……被夷為平地了!我們沒能阻止他們。', '城鎮……被夷為平地了!我們沒能阻止他們。', '他們打開了通往火焰之地的門戶……拜託告訴我還有希望!', '他們打開了通往火焰之地的門戶……拜託告訴我還有希望!');
DELETE FROM `npc_text_locale` WHERE `ID` = 16097 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16097, 'zhTW', '獸人，在我有生之年我還沒看過這種...', NULL, '我們在這裡的裝備嚴重不足，難以應戰。$B$B必須先做好準備才行...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16099 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16099, 'zhTW', '士氣越來越高了，謝謝你的努力，$c。', NULL, '如果我們能找到辦法殺出重圍，地獄吼一定會知道你的功績，$r。', NULL, '我跟這些獸人一起並肩作戰過無數場戰役。$B$B我可不羨慕任何敢闖進這裡的納迦。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16126 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16126, 'zhTW', '我們的戰士...現在他們全都變成俘虜了。', NULL, '我們之中有許多人試圖逃離納迦的追擊。$B$B只有我一個人成功了...', NULL, '這根本說不通，但那些畜生似乎不惜一切代價要讓我們的部隊活下來...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16180 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16180, 'zhTW', '有人用這些燒杯和鏈金術工具在試驗各種不同的潛水艇燃料。', '有人用這些燒杯和鏈金術工具在試驗各種不同的潛水艇燃料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16182 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16182, 'zhTW', '你的面前有幾個少量的油料樣本，還有一個空的燒杯。這個燒杯大概裝得下五份樣本。$B$B你要先加哪種油進去?', '你的面前有幾個少量的油料樣本，還有一個空的燒杯。這個燒杯大概裝得下五份樣本。$B$B你要先加哪種油進去?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16183 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16183, 'zhTW', '你接下來會加哪種油進去?', '你接下來會加哪種油進去?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16184 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16184, 'zhTW', '你現在有兩種作為樣本的油。你接下來會選擇哪個?', '你現在有兩種作為樣本的油。你接下來會選擇哪個?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
